 $('#auth-subtitle').textContent=mode==='register'?label+' · Para crear tu cuenta necesitás un código de invitación generado por administración.':role==='admin'?'Acceso privado de administración.':role==='pasajero'?'Ingresá con tu usuario y contraseña de pasajero.':'Ingresá con tu usuario y contraseña de conductor.';
 $('#auth-form-wrap').innerHTML='<button class="auth-back" id="auth-back">← Volver</button><form class="auth-fields" id="auth-form">'+(mode==='register'?'<label>Nombre para mostrar<input name="display_name" maxlength="60" required autocomplete="name"></label>':'')+'<label>Usuario<input name="username" minlength="3" maxlength="24" required autocomplete="username" autocapitalize="none"></label><label>Contraseña<input name="password" type="password" minlength="10" maxlength="128" required autocomplete="'+(mode==='login'?'current-password':'new-password')+'"></label>'+ (mode==='register'?'<label>Código de invitación<input name="invite_code" required autocomplete="off" placeholder="WV-…"></label>':'')+'<div class="auth-actions"><button class="btn" type="submit">'+(mode==='login'?'Ingresar':role==='admin'?'Activar administración':'Crear cuenta')+'</button></div></form><div class="auth-switch">'+(mode==='login'?(role==='pasajero'?'¿Todavía no tenés cuenta? ':'¿Tenés una invitación del administrador? '):'¿Ya tenés cuenta? ')+'<button id="auth-switch">'+(mode==='login'?'Crear cuenta':'Ingresar')+'</button></div>';
 $('#auth-back').onclick=()=>{role=null;error('');drawAuth();};
 $('#auth-switch').onclick=()=>{mode=mode==='login'?'register':'login';error('');drawAuth();};
 $('#auth-form').onsubmit=async e=>{e.preventDefault();error('');const fd=new FormData(e.currentTarget);const b={action:mode,role,username:fd.get('username'),password:fd.get('password')};if(mode==='register'){b.display_name=fd.get('display_name');b.invite_code=fd.get('invite_code');}const btn=e.currentTarget.querySelector('button[type=submit]');btn.disabled=true;btn.textContent='Conectando…';try{const out=await api(b);if(out.session){const {error:setErr}=await sb.auth.setSession({access_token:out.session.access_token,refresh_token:out.session.refresh_token});if(setErr)throw setErr;}profile=out.profile;enterApp();}catch(err){error(err.message);}finally{btn.disabled=false;btn.textContent=mode==='login'?'Ingresar':'Crear cuenta';}};
