 page.innerHTML=panel('Solicitar un viaje','<form id="request-form" class="client-form"><label>Origen · calle y número<input name="origin" required maxlength="120" placeholder="Ej.: San Martín 123"></label><label>Destino<input name="destination" required maxlength="120"></label><label>Fecha y hora<input name="travel_at" type="datetime-local"></label><label>Cantidad de pasajeros<input name="passengers" type="number" min="1" max="20" value="1" required></label><label style="grid-column:1/-1">Aclaraciones<textarea name="notes" maxlength="1000"></textarea></label><button class="btn" type="submit">Enviar solicitud</button></form>')+panel('Mis solicitudes',cards||'<p class="client-muted">Todavía no enviaste solicitudes.</p>');
